from app.main import app
AUTH = {"require_user", "require_admin", "require_account_for_writes", "require_financial_consent"}
SAFE = {"GET", "HEAD", "OPTIONS"}
open_writes = []
for r in app.routes:
    methods = getattr(r, "methods", set()) - SAFE
    if not methods or not str(getattr(r, "path", "")).startswith("/api"):
        continue
    names = {d.call.__name__ for d in getattr(r.dependant, "dependencies", []) if getattr(d, "call", None)}
    # вложенные зависимости
    stack = list(getattr(r.dependant, "dependencies", []))
    while stack:
        d = stack.pop()
        if getattr(d, "call", None):
            names.add(d.call.__name__)
        stack.extend(getattr(d, "dependencies", []))
    if not (names & AUTH):
        open_writes.append((sorted(methods), r.path))
print("пишущих ручек без гейта:", len(open_writes))
for m, p in open_writes[:20]:
